CREATE PROCEDURE [tb_app].[GetClientExternalIdentities]
    @ClientId int = NULL,
    @SourceSystem nvarchar(40) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @UserSid varbinary(85);
