IF
(
    SELECT COUNT(*)
    FROM sys.parameters
    WHERE [object_id] = OBJECT_ID(N'tb_app.AdminSaveOrganizationTag')
) <> 4
   OR NOT EXISTS
   (
       SELECT 1
       FROM sys.parameters
       WHERE [object_id] = OBJECT_ID(N'tb_app.AdminSaveOrganizationTag')
         AND [parameter_id] = 1
         AND [name] = N'@Id'
         AND TYPE_NAME([user_type_id]) = N'int'
   )
   OR NOT EXISTS
   (
       SELECT 1
       FROM sys.parameters
       WHERE [object_id] = OBJECT_ID(N'tb_app.AdminSaveOrganizationTag')
         AND [parameter_id] = 2
         AND [name] = N'@Tag'
         AND TYPE_NAME([user_type_id]) = N'nvarchar'
         AND [max_length] = 2000
   )
   OR NOT EXISTS
   (
       SELECT 1
       FROM sys.parameters
       WHERE [object_id] = OBJECT_ID(N'tb_app.AdminSaveOrganizationTag')
         AND [parameter_id] = 3
         AND [name] = N'@ExpectedRowVersion'
         AND TYPE_NAME([user_type_id]) = N'binary'
         AND [max_length] = 8
   )
   OR NOT EXISTS
   (
