(
    [ObjectName] nvarchar(300) NOT NULL PRIMARY KEY,
    [ObjectType] char(2) NOT NULL
);
INSERT INTO @RequiredObjects([ObjectName], [ObjectType]) VALUES
    (N'tb_sync.SageSyncRequests', N'U'),
