IF CHARINDEX(N'CONVERT(int, 11) AS [SchemaVersion]',
    OBJECT_DEFINITION(OBJECT_ID(N'tb_app.GetRepositoryCapabilities', N'P'))) = 0
   AND CHARINDEX(N'CONVERT(int, 12) AS [SchemaVersion]',
