-- ============================================================================
-- BEGIN 102-V0013-WhdClientContactDetailsVerify.sql
-- ============================================================================

:ON ERROR EXIT

USE [$(DatabaseName)];
GO

SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @FailureCount int = 0;

IF NOT EXISTS
(
    SELECT 1
    FROM [tb_deploy].[SchemaMigrations]
    WHERE [MigrationId] = N'SqlServer2016.WhdClientContactDetails.0013'
      AND [SchemaVersion] = 13
)
BEGIN
    PRINT N'FAIL: V0013 WHD client contact migration is not installed.';
    SET @FailureCount += 1;
END;

IF COL_LENGTH(N'tb_data.Clients', N'WhdContactEmail') IS NULL
   OR COL_LENGTH(N'tb_data.Clients', N'WhdPhone') IS NULL
   OR COL_LENGTH(N'tb_data.Clients', N'WhdAddress') IS NULL
BEGIN
    PRINT N'FAIL: one or more WHD client contact columns are missing.';
    SET @FailureCount += 1;
END;

DECLARE @CapabilitiesDefinition nvarchar(max) =
    OBJECT_DEFINITION(OBJECT_ID(N'tb_app.GetRepositoryCapabilities', N'P'));
DECLARE @SearchDefinition nvarchar(max) =
    OBJECT_DEFINITION(OBJECT_ID(N'tb_app.SearchClients', N'P'));
DECLARE @GetDefinition nvarchar(max) =
    OBJECT_DEFINITION(OBJECT_ID(N'tb_app.GetClient', N'P'));
DECLARE @ApplyDefinition nvarchar(max) =
    OBJECT_DEFINITION(OBJECT_ID(N'tb_service.ApplyWhdClientSnapshot', N'P'));

IF CHARINDEX(N'CONVERT(int, 13) AS [SchemaVersion]', COALESCE(@CapabilitiesDefinition, N'')) = 0
   AND CHARINDEX(N'CONVERT(int, 14) AS [SchemaVersion]', COALESCE(@CapabilitiesDefinition, N'')) = 0
   AND CHARINDEX(N'CONVERT(int, 15) AS [SchemaVersion]', COALESCE(@CapabilitiesDefinition, N'')) = 0
BEGIN
    PRINT N'FAIL: repository capabilities do not report schema version 13 or 14.';
    SET @FailureCount += 1;
END;

IF CHARINDEX(N'client.[WhdContactEmail]', COALESCE(@SearchDefinition, N'')) = 0
   OR CHARINDEX(N'client.[WhdPhone]', COALESCE(@SearchDefinition, N'')) = 0
   OR CHARINDEX(N'client.[WhdAddress]', COALESCE(@SearchDefinition, N'')) = 0
   OR CHARINDEX(N'client.[WhdContactEmail]', COALESCE(@GetDefinition, N'')) = 0
BEGIN
    PRINT N'FAIL: approved client readers do not return WHD contact details.';
    SET @FailureCount += 1;
END;

IF CHARINDEX(N'[ContactEmail] nvarchar(255) ''$.contactEmail''', COALESCE(@ApplyDefinition, N'')) = 0
   OR CHARINDEX(N'[WhdContactEmail]', COALESCE(@ApplyDefinition, N'')) = 0
   OR CHARINDEX(N'[WhdPhone]', COALESCE(@ApplyDefinition, N'')) = 0
   OR CHARINDEX(N'[WhdAddress]', COALESCE(@ApplyDefinition, N'')) = 0
BEGIN
    PRINT N'FAIL: WHD synchronization does not persist the new contact details.';
    SET @FailureCount += 1;
END;

IF @FailureCount > 0
    THROW 52100, N'TechBench V0013 WHD client contact verification failed.', 1;

PRINT N'TechBench V0013 WHD client contact verification passed.';
GO

-- ============================================================================
-- END 102-V0013-WhdClientContactDetailsVerify.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 103-V0014-EquipmentBoardVerify.sql
-- ============================================================================

:ON ERROR EXIT

USE [$(DatabaseName)];
GO

SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @FailureCount int=0;

IF NOT EXISTS
(
    SELECT 1
    FROM [tb_deploy].[SchemaMigrations]
    WHERE [MigrationId]=N'SqlServer2016.EquipmentBoard.0014'
      AND [SchemaVersion]=14
)
BEGIN
    PRINT N'FAIL: V0014 equipment-board migration is not installed.';
    SET @FailureCount+=1;
END;

IF OBJECT_ID(N'tb_inventory.Equipment', N'U') IS NULL
BEGIN
    PRINT N'FAIL: the equipment table is missing.';
    SET @FailureCount+=1;
END;

IF OBJECT_ID(N'tb_inventory.ClientUsers', N'U') IS NULL
BEGIN
    PRINT N'FAIL: the inventory client-user table is missing.';
    SET @FailureCount+=1;
END;

IF OBJECT_ID(N'tb_inventory.ClientUserAccounts', N'U') IS NULL
BEGIN
    PRINT N'FAIL: the inventory client-user account table is missing.';
    SET @FailureCount+=1;
END;

IF OBJECT_ID(N'tb_inventory.ClientUserAccountFields', N'U') IS NULL
BEGIN
    PRINT N'FAIL: the encrypted client-user account-field table is missing.';
    SET @FailureCount+=1;
END;

IF OBJECT_ID(N'tb_inventory.EquipmentAssignmentHistory', N'U') IS NULL
BEGIN
    PRINT N'FAIL: the equipment assignment-history table is missing.';
    SET @FailureCount+=1;
END;

IF COL_LENGTH(N'tb_inventory.ClientUsers', N'SourceRowHash') IS NULL
BEGIN
    PRINT N'FAIL: client users cannot track workbook row changes.';
    SET @FailureCount+=1;
END;

IF COL_LENGTH(N'tb_inventory.Equipment', N'WorkflowStage') IS NULL
   OR COL_LENGTH(N'tb_inventory.Equipment', N'AssetTag') IS NULL
   OR COL_LENGTH(N'tb_inventory.Equipment', N'ClientId') IS NULL
   OR COL_LENGTH(N'tb_inventory.Equipment', N'ClientUserId') IS NULL
   OR COL_LENGTH(N'tb_inventory.Equipment', N'LocationName') IS NULL
BEGIN
    PRINT N'FAIL: one or more client/user-aware equipment columns are missing.';
    SET @FailureCount+=1;
END;

DECLARE @RequiredProcedures TABLE ([ObjectName] nvarchar(256) NOT NULL PRIMARY KEY);
INSERT INTO @RequiredProcedures([ObjectName]) VALUES
    (N'tb_app.AdminGetEquipmentBoard'),
    (N'tb_app.AdminGetInventoryClients'),
    (N'tb_app.AdminGetEquipmentAssignmentHistory'),
    (N'tb_app.AdminSaveEquipment'),
    (N'tb_app.AdminMoveEquipment'),
    (N'tb_app.AdminArchiveEquipment');

IF EXISTS
(
    SELECT 1
    FROM @RequiredProcedures
    WHERE OBJECT_ID([ObjectName], N'P') IS NULL
)
BEGIN
    PRINT N'FAIL: one or more equipment-board procedures are missing.';
    SET @FailureCount+=1;
END;

IF OBJECT_ID(N'tb_service.ApplyCredentialsClientUserSnapshot', N'P') IS NULL
BEGIN
    PRINT N'FAIL: the Credentials client-user import procedure is missing.';
    SET @FailureCount+=1;
END
ELSE IF CHARINDEX(
    N'OPENJSON(person_row.[AccountsJson])',
    COALESCE(
        OBJECT_DEFINITION(
            OBJECT_ID(N'tb_service.ApplyCredentialsClientUserSnapshot', N'P')),
        N''))=0
    OR CHARINDEX(
        N'[tb_inventory].[ClientUserAccounts]',
        COALESCE(
            OBJECT_DEFINITION(
                OBJECT_ID(N'tb_service.ApplyCredentialsClientUserSnapshot', N'P')),
            N''))=0
    OR CHARINDEX(
        N'[tb_inventory].[ClientUserAccountFields]',
        COALESCE(
            OBJECT_DEFINITION(
                OBJECT_ID(N'tb_service.ApplyCredentialsClientUserSnapshot', N'P')),
            N''))=0
    OR CHARINDEX(
        N'EncryptByKey',
        COALESCE(
            OBJECT_DEFINITION(
                OBJECT_ID(N'tb_service.ApplyCredentialsClientUserSnapshot', N'P')),
            N''))=0
BEGIN
    PRINT N'FAIL: the Credentials client-user import does not parse and encrypt account fields.';
    SET @FailureCount+=1;
END;

IF OBJECT_ID(N'tb_service.ApplyCredentialsClientUserSnapshot', N'P') IS NOT NULL
   AND NOT EXISTS
   (
       SELECT 1
       FROM sys.database_permissions
       WHERE [grantee_principal_id]=DATABASE_PRINCIPAL_ID(N'tb_role_sync_service')
         AND [major_id]=OBJECT_ID(N'tb_service.ApplyCredentialsClientUserSnapshot')
         AND [permission_name]=N'EXECUTE'
         AND [state] IN (N'G',N'W')
   )
BEGIN
    PRINT N'FAIL: the Sync Service cannot import Credentials client users.';
    SET @FailureCount+=1;
END;

DECLARE @ClientUserReadProcedures TABLE ([ObjectName] nvarchar(256) NOT NULL PRIMARY KEY);
INSERT INTO @ClientUserReadProcedures([ObjectName]) VALUES
    (N'tb_app.SearchClientUsers'),
    (N'tb_app.RevealClientUser'),
    (N'tb_app.GetEquipmentInventory');

IF EXISTS
(
    SELECT 1 FROM @ClientUserReadProcedures
    WHERE OBJECT_ID([ObjectName], N'P') IS NULL
)
BEGIN
    PRINT N'FAIL: one or more client-user read procedures are missing.';
    SET @FailureCount+=1;
END;

IF EXISTS
(
    SELECT role_name.[RoleName], required.[ObjectName]
    FROM (VALUES (N'tb_role_user'), (N'tb_role_admin')) role_name([RoleName])
    CROSS JOIN @ClientUserReadProcedures required
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM sys.database_permissions
        WHERE [grantee_principal_id]=DATABASE_PRINCIPAL_ID(role_name.[RoleName])
          AND [major_id]=OBJECT_ID(required.[ObjectName])
          AND [permission_name]=N'EXECUTE'
          AND [state] IN (N'G',N'W')
    )
)
BEGIN
    PRINT N'FAIL: one or more client-user read grants are missing.';
    SET @FailureCount+=1;
END;

IF EXISTS
(
    SELECT 1
    FROM sys.database_permissions permission_row
    INNER JOIN @ClientUserReadProcedures required
        ON OBJECT_ID(required.[ObjectName])=permission_row.[major_id]
    WHERE permission_row.[grantee_principal_id] IN
    (
        DATABASE_PRINCIPAL_ID(N'tb_preview_reader'),
        DATABASE_PRINCIPAL_ID(N'tb_role_sync_service')
    )
      AND permission_row.[permission_name]=N'EXECUTE'
      AND permission_row.[state] IN (N'G',N'W')
)
BEGIN
    PRINT N'FAIL: preview or Sync Service can execute a client-user read procedure.';
    SET @FailureCount+=1;
END;

IF CHARINDEX(
    N'DecryptByKeyAutoCert',
    COALESCE(OBJECT_DEFINITION(OBJECT_ID(N'tb_app.RevealClientUser', N'P')), N''))=0
   OR CHARINDEX(
    N'ClientUserAccountId',
    COALESCE(OBJECT_DEFINITION(OBJECT_ID(N'tb_app.RevealClientUser', N'P')), N''))=0
BEGIN
    PRINT N'FAIL: client-user reveal does not decrypt account fields with their account authenticator.';
    SET @FailureCount+=1;
END;

DECLARE @EquipmentInventoryDefinition nvarchar(max)=
    COALESCE(OBJECT_DEFINITION(OBJECT_ID(N'tb_app.GetEquipmentInventory', N'P')), N'');

IF CHARINDEX(N'@ClientId', @EquipmentInventoryDefinition)=0
   OR CHARINDEX(N'@ClientUserId', @EquipmentInventoryDefinition)=0
   OR CHARINDEX(N'@ClientName', @EquipmentInventoryDefinition)=0
   OR CHARINDEX(N'equipment.[IsArchived] = 0', @EquipmentInventoryDefinition)=0
BEGIN
    PRINT N'FAIL: the shared equipment inventory read is not client-scoped and archive-safe.';
    SET @FailureCount+=1;
END;

DECLARE @RepositoryCapabilitiesDefinition nvarchar(max)=
    COALESCE(OBJECT_DEFINITION(OBJECT_ID(N'tb_app.GetRepositoryCapabilities', N'P')), N'');

IF CHARINDEX(N'CONVERT(int, 14) AS [SchemaVersion]', @RepositoryCapabilitiesDefinition)=0
   AND CHARINDEX(N'CONVERT(int, 15) AS [SchemaVersion]', @RepositoryCapabilitiesDefinition)=0
BEGIN
    PRINT N'FAIL: repository capabilities do not report schema version 14.';
    SET @FailureCount+=1;
END;

DECLARE @RequiredCapabilityTokens TABLE ([Token] nvarchar(128) NOT NULL PRIMARY KEY);
INSERT INTO @RequiredCapabilityTokens([Token]) VALUES
    (N'[FullTextSearchAvailable]'),
    (N'[SupportsTickets]'),
    (N'[SupportsWorkEntries]'),
    (N'[SupportsPrivateNotes]'),
    (N'[SupportsPostingLeases]'),
    (N'[SupportsSyncLeases]'),
    (N'[SupportsImports]'),
    (N'[SupportsTechBenchV1Import]'),
    (N'[SupportsServerSageSync]'),
    (N'[SupportsAdminUserPreview]'),
    (N'[SupportsFireDrillCredentials]'),
    (N'[EquipmentBoardAvailable]');

IF EXISTS
(
    SELECT 1
    FROM @RequiredCapabilityTokens
    WHERE CHARINDEX([Token], @RepositoryCapabilitiesDefinition)=0
)
BEGIN
    PRINT N'FAIL: repository capabilities dropped one or more capabilities introduced by an earlier schema version.';
    SET @FailureCount+=1;
END;

IF CHARINDEX(
    N'@TargetWorkflowStage',
    COALESCE(OBJECT_DEFINITION(OBJECT_ID(N'tb_app.AdminMoveEquipment', N'P')), N''))=0
BEGIN
    PRINT N'FAIL: equipment assignment does not persist Stock, Assigned, and Deployment stages.';
    SET @FailureCount+=1;
END;

IF CHARINDEX(
    N'@SourceStage NOT IN (N''Assigned'', N''Deployment'', N''Deployed'')',
    COALESCE(OBJECT_DEFINITION(OBJECT_ID(N'tb_app.AdminMoveEquipment', N'P')), N''))=0
BEGIN
    PRINT N'FAIL: equipment priority maintenance does not isolate each technician deployment lane.';
    SET @FailureCount+=1;
END;

IF CHARINDEX(
    N'@ClientUserId',
    COALESCE(OBJECT_DEFINITION(OBJECT_ID(N'tb_app.AdminSaveEquipment', N'P')), N''))=0
   OR CHARINDEX(
    N'[tb_inventory].[EquipmentAssignmentHistory]',
    COALESCE(OBJECT_DEFINITION(OBJECT_ID(N'tb_app.AdminSaveEquipment', N'P')), N''))=0
BEGIN
    PRINT N'FAIL: equipment saves do not validate client users or record assignment history.';
    SET @FailureCount+=1;
END;

IF EXISTS
(
    SELECT required.[ObjectName]
    FROM @RequiredProcedures AS required
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM sys.database_permissions
        WHERE [grantee_principal_id]=DATABASE_PRINCIPAL_ID(N'tb_role_admin')
          AND [major_id]=OBJECT_ID(required.[ObjectName])
          AND [permission_name]=N'EXECUTE'
          AND [state] IN (N'G',N'W')
    )
)
BEGIN
    PRINT N'FAIL: one or more Admin equipment-board grants are missing.';
    SET @FailureCount+=1;
END;

IF EXISTS
(
    SELECT 1
    FROM sys.database_permissions AS permission_row
    INNER JOIN @RequiredProcedures AS required
        ON OBJECT_ID(required.[ObjectName])=permission_row.[major_id]
    WHERE permission_row.[grantee_principal_id] IN
    (
        DATABASE_PRINCIPAL_ID(N'tb_role_user'),
        DATABASE_PRINCIPAL_ID(N'tb_preview_reader')
    )
      AND permission_row.[permission_name]=N'EXECUTE'
      AND permission_row.[state] IN (N'G',N'W')
)
BEGIN
    PRINT N'FAIL: a non-Admin principal can execute an equipment-board procedure.';
    SET @FailureCount+=1;
END;

IF EXISTS
(
    SELECT 1
    FROM sys.database_permissions
    WHERE [grantee_principal_id] IN
    (
        DATABASE_PRINCIPAL_ID(N'tb_role_user'),
        DATABASE_PRINCIPAL_ID(N'tb_role_admin'),
        DATABASE_PRINCIPAL_ID(N'tb_role_sync_service'),
        DATABASE_PRINCIPAL_ID(N'tb_preview_reader')
    )
      AND [major_id] IN
      (
          OBJECT_ID(N'tb_inventory.Equipment'),
          OBJECT_ID(N'tb_inventory.ClientUsers'),
          OBJECT_ID(N'tb_inventory.ClientUserAccounts'),
          OBJECT_ID(N'tb_inventory.ClientUserAccountFields'),
          OBJECT_ID(N'tb_inventory.EquipmentAssignmentHistory')
      )
      AND [permission_name] IN (N'SELECT',N'INSERT',N'UPDATE',N'DELETE',N'CONTROL',N'ALTER')
      AND [state] IN (N'G',N'W')
)
BEGIN
    PRINT N'FAIL: a TechBench principal has a direct inventory-table grant.';
    SET @FailureCount+=1;
END;

IF CHARINDEX(
    N'IS_ROLEMEMBER(N''tb_role_admin'')',
    REPLACE(
        COALESCE(OBJECT_DEFINITION(OBJECT_ID(N'tb_app.AdminMoveEquipment', N'P')), N''),
        N' ',
        N''))=0
BEGIN
    PRINT N'FAIL: equipment assignment does not enforce Admin access.';
    SET @FailureCount+=1;
END;

IF @FailureCount>0
    THROW 52220, N'TechBench V0014 equipment-board verification failed.', 1;

PRINT N'TechBench V0014 equipment-board verification passed.';
GO

-- ============================================================================
-- END 103-V0014-EquipmentBoardVerify.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 104-V0015-EquipmentAnyDeskVerify.sql
-- ============================================================================

:ON ERROR EXIT

USE [$(DatabaseName)];
GO

SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @FailureCount int=0;

IF NOT EXISTS
(
    SELECT 1
    FROM [tb_deploy].[SchemaMigrations]
    WHERE [MigrationId]=N'SqlServer2016.EquipmentAnyDesk.0015'
      AND [SchemaVersion]=15
)
BEGIN
    PRINT N'FAIL: V0015 equipment AnyDesk migration is not installed.';
    SET @FailureCount+=1;
END;

IF COL_LENGTH(N'tb_inventory.Equipment', N'AnyDeskNumber') IS NULL
   OR COL_LENGTH(N'tb_inventory.Equipment', N'AnyDeskPasswordEncrypted') IS NULL
BEGIN
    PRINT N'FAIL: one or more equipment AnyDesk columns are missing.';
    SET @FailureCount+=1;
END;

DECLARE @CapabilitiesDefinition nvarchar(max)=
    COALESCE(OBJECT_DEFINITION(OBJECT_ID(N'tb_app.GetRepositoryCapabilities', N'P')), N'');
IF CHARINDEX(N'CONVERT(int, 15) AS [SchemaVersion]', @CapabilitiesDefinition)=0
BEGIN
    PRINT N'FAIL: repository capabilities do not report schema version 15.';
    SET @FailureCount+=1;
END;

DECLARE @InventoryDefinition nvarchar(max)=
    COALESCE(OBJECT_DEFINITION(OBJECT_ID(N'tb_app.GetEquipmentInventory', N'P')), N'');
IF CHARINDEX(N'equipment.[AnyDeskNumber]', @InventoryDefinition)=0
   OR CHARINDEX(N'CAST(N'''' AS nvarchar(max)) AS [AnyDeskPassword]', @InventoryDefinition)=0
   OR CHARINDEX(N'DecryptByKey', @InventoryDefinition)>0
   OR CHARINDEX(N'[AnyDeskPasswordEncrypted]', @InventoryDefinition)>0
BEGIN
    PRINT N'FAIL: shared inventory reads do not expose the number while keeping the AnyDesk password private.';
    SET @FailureCount+=1;
END;

DECLARE @AdminReadDefinition nvarchar(max)=
    COALESCE(OBJECT_DEFINITION(OBJECT_ID(N'tb_app.AdminGetEquipmentBoard', N'P')), N'');
DECLARE @SecureReadDefinition nvarchar(max)=
    COALESCE(OBJECT_DEFINITION(OBJECT_ID(N'tb_app.AdminGetEquipmentBoardSecure', N'P')), N'');
DECLARE @AdminSaveDefinition nvarchar(max)=
    COALESCE(OBJECT_DEFINITION(OBJECT_ID(N'tb_app.AdminSaveEquipment', N'P')), N'');
DECLARE @EncryptDefinition nvarchar(max)=
    COALESCE(OBJECT_DEFINITION(OBJECT_ID(N'tb_security.EncryptEquipmentAnyDeskPassword', N'P')), N'');
DECLARE @EnsureCurrentUserDefinition nvarchar(max)=
    COALESCE(OBJECT_DEFINITION(OBJECT_ID(N'tb_security.EnsureCurrentUser', N'P')), N'');

IF CHARINDEX(N'IS_ROLEMEMBER(N''tb_role_admin'')', @AdminReadDefinition)=0
   OR CHARINDEX(N'AdminGetEquipmentBoardSecure', @AdminReadDefinition)=0
   OR CHARINDEX(N'WITH EXECUTE AS OWNER', @AdminReadDefinition)>0
   OR CHARINDEX(N'equipment.[AnyDeskNumber]', @SecureReadDefinition)=0
   OR CHARINDEX(N'DecryptByKeyAutoCert', @SecureReadDefinition)=0
   OR CHARINDEX(N'WITH EXECUTE AS OWNER', @SecureReadDefinition)=0
   OR CHARINDEX(N'@AnyDeskNumber nvarchar(80)', @AdminSaveDefinition)=0
   OR CHARINDEX(N'@AnyDeskPassword nvarchar(max)', @AdminSaveDefinition)=0
   OR CHARINDEX(N'IS_ROLEMEMBER(N''tb_role_admin'')', @AdminSaveDefinition)=0
   OR CHARINDEX(N'EncryptEquipmentAnyDeskPassword', @AdminSaveDefinition)=0
   OR CHARINDEX(N'WITH EXECUTE AS OWNER', @AdminSaveDefinition)>0
   OR CHARINDEX(N'[AnyDeskPasswordEncrypted]', @AdminSaveDefinition)=0
   OR CHARINDEX(N'EncryptByKey', @EncryptDefinition)=0
   OR CHARINDEX(N'WITH EXECUTE AS OWNER', @EncryptDefinition)=0
BEGIN
    PRINT N'FAIL: caller-authorized Admin equipment procedures do not securely delegate AnyDesk cryptography to owner-executed helpers.';
    SET @FailureCount+=1;
END;

IF CHARINDEX(
    N'IS_ROLEMEMBER(N''tb_role_admin'')',
    @EnsureCurrentUserDefinition)=0
   OR CHARINDEX(
        N'IS_ROLEMEMBER(N''tb_role_admin'', ORIGINAL_LOGIN())',
        @EnsureCurrentUserDefinition)>0
BEGIN
    PRINT N'FAIL: current-user role detection is not running in the authenticated caller context required for Windows group membership.';
    SET @FailureCount+=1;
END;

IF EXISTS
(
    SELECT 1
    FROM sys.database_permissions AS permission
    WHERE permission.[class]=1
      AND permission.[major_id] IN
      (
          OBJECT_ID(N'tb_app.AdminGetEquipmentBoardSecure', N'P'),
          OBJECT_ID(N'tb_security.EncryptEquipmentAnyDeskPassword', N'P')
      )
      AND permission.[permission_name]=N'EXECUTE'
      AND permission.[state] IN (N'G', N'W')
      AND permission.[grantee_principal_id] IN
      (
          USER_ID(N'tb_role_user'),
          USER_ID(N'tb_role_admin'),
          USER_ID(N'tb_role_sync_service'),
          USER_ID(N'tb_preview_reader')
      )
)
BEGIN
    PRINT N'FAIL: an owner-executed equipment encryption helper has a direct application-role grant.';
    SET @FailureCount+=1;
END;

IF CHARINDEX(N'[AnyDeskPassword] nvarchar', @AdminSaveDefinition)>0
   OR COL_LENGTH(N'tb_inventory.Equipment', N'AnyDeskPassword') IS NOT NULL
BEGIN
    PRINT N'FAIL: an AnyDesk password can be persisted as plaintext.';
    SET @FailureCount+=1;
END;

IF @FailureCount>0
    THROW 52221, N'TechBench V0015 equipment AnyDesk verification failed.', 1;

PRINT N'TechBench V0015 equipment AnyDesk verification passed.';
GO

-- ============================================================================
-- END 104-V0015-EquipmentAnyDeskVerify.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 105-V0015-EquipmentDeploymentLifecycleVerify.sql
-- ============================================================================

:ON ERROR EXIT

USE [$(DatabaseName)];
GO

SET NOCOUNT ON;

DECLARE @Failures int = 0;

DECLARE @EquipmentConstraint nvarchar(max) =
    COALESCE
    (
        (
            SELECT [definition]
            FROM sys.check_constraints
            WHERE [parent_object_id] =
                OBJECT_ID(N'tb_inventory.Equipment', N'U')
              AND [name] = N'CK_Equipment_WorkflowStage'
        ),
        N''
    );
DECLARE @HistoryConstraint nvarchar(max) =
    COALESCE
    (
        (
            SELECT [definition]
            FROM sys.check_constraints
            WHERE [parent_object_id] =
                OBJECT_ID(N'tb_inventory.EquipmentAssignmentHistory', N'U')
              AND [name] =
                N'CK_EquipmentAssignmentHistory_WorkflowStage'
        ),
        N''
    );

IF CHARINDEX(N'Deployed', @EquipmentConstraint) = 0
BEGIN
    PRINT N'FAIL: Equipment workflow constraint does not allow Deployed.';
    SET @Failures += 1;
END;

IF CHARINDEX(N'Deployed', @HistoryConstraint) = 0
BEGIN
    PRINT N'FAIL: Equipment history workflow constraint does not allow Deployed.';
    SET @Failures += 1;
END;

DECLARE @CapabilitiesDefinition nvarchar(max) =
    COALESCE
    (
        OBJECT_DEFINITION(
            OBJECT_ID(N'tb_app.GetRepositoryCapabilities', N'P')),
        N''
    );
IF CHARINDEX(
       N'CONVERT(int, 15) AS [SchemaVersion]',
       @CapabilitiesDefinition) = 0
BEGIN
    PRINT N'FAIL: Repository capabilities do not preserve schema version 15.';
    SET @Failures += 1;
END;

DECLARE @MoveDefinition nvarchar(max) =
    COALESCE
    (
        OBJECT_DEFINITION(OBJECT_ID(N'tb_app.AdminMoveEquipment', N'P')),
        N''
    );
IF CHARINDEX(N'N''Deployed''', @MoveDefinition) = 0
   OR CHARINDEX(N'N''Equipment deployment completed.''', @MoveDefinition) = 0
BEGIN
    PRINT N'FAIL: Equipment move procedure does not persist and log deployed completion.';
    SET @Failures += 1;
END;

DECLARE @BoardDefinition nvarchar(max) =
    COALESCE
    (
        OBJECT_DEFINITION(OBJECT_ID(N'tb_app.AdminGetEquipmentBoard', N'P')),
        N''
    );
DECLARE @SecureBoardDefinition nvarchar(max) =
    COALESCE
    (
        OBJECT_DEFINITION(
            OBJECT_ID(N'tb_app.AdminGetEquipmentBoardSecure', N'P')),
        N''
    );
IF CHARINDEX(N'@IncludeDeployed', @BoardDefinition) = 0
   OR CHARINDEX(N'@IncludeDeployed', @SecureBoardDefinition) = 0
   OR CHARINDEX(N'[WorkflowStage] <> N''Deployed''', @SecureBoardDefinition) = 0
BEGIN
    PRINT N'FAIL: Stable-compatible equipment board filtering is not installed.';
    SET @Failures += 1;
END;

IF @Failures > 0
    THROW 52222, N'TechBench equipment deployment lifecycle verification failed.', 1;

PRINT N'TechBench schema-15-compatible equipment deployment lifecycle verification passed.';
GO

-- ============================================================================
-- END 105-V0015-EquipmentDeploymentLifecycleVerify.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 106-V0015-ClientInfoBetaVerify.sql
-- ============================================================================

:ON ERROR EXIT

USE [$(DatabaseName)];
GO

SET NOCOUNT ON;

IF NOT EXISTS
(
    SELECT 1
    FROM [tb_deploy].[SchemaMigrations]
    WHERE [MigrationId]=N'SqlServer2016.ClientInfoBeta.0015'
      AND [SchemaVersion]=15
)
    THROW 52500,N'Client Info beta migration record is missing.',1;

IF (SELECT MAX([SchemaVersion]) FROM [tb_deploy].[SchemaMigrations])<>15
    THROW 52501,N'Client Info beta must remain compatible with stable schema version 15.',1;

DECLARE @MissingObjects TABLE([ObjectName] nvarchar(256) NOT NULL);
INSERT INTO @MissingObjects([ObjectName])
SELECT required.[ObjectName]
FROM
(
    VALUES
        (N'tb_client.ClientProfiles',N'U'),
        (N'tb_client.Locations',N'U'),
        (N'tb_client.People',N'U'),
        (N'tb_client.Resources',N'U'),
        (N'tb_client.ResourceFields',N'U'),
        (N'tb_client.Credentials',N'U'),
        (N'tb_client.CredentialSecrets',N'U'),
        (N'tb_client.ClientFacts',N'U'),
        (N'tb_client.SourceDocuments',N'U'),
        (N'tb_client.RecordProvenance',N'U'),
        (N'tb_import.ClientInfoBatches',N'U'),
        (N'tb_import.ClientInfoRecords',N'U'),
        (N'tb_import.ClientInfoSecrets',N'U'),
        (N'tb_import.ClientInfoIssues',N'U'),
        (N'tb_import.ClientInfoPromotionMap',N'U'),
        (N'tb_ops.ClientInfoCutovers',N'U'),
        (N'tb_app.SearchClientInfoClients',N'P'),
        (N'tb_app.GetClientInfoSnapshot',N'P'),
        (N'tb_app.SaveClientInfoProfile',N'P'),
        (N'tb_app.SaveClientInfoLocation',N'P'),
        (N'tb_app.SaveClientInfoPerson',N'P'),
        (N'tb_app.SaveClientInfoResource',N'P'),
        (N'tb_app.SaveClientInfoResourceField',N'P'),
        (N'tb_app.DeleteClientInfoResourceField',N'P'),
        (N'tb_app.SaveClientInfoFact',N'P'),
        (N'tb_app.SaveClientCredential',N'P'),
        (N'tb_security.EncryptClientSecretValue',N'P'),
        (N'tb_app.SetClientCredentialSecret',N'P'),
        (N'tb_app.RevealClientCredentialSecret',N'P'),
        (N'tb_app.BeginClientInfoImport',N'P'),
        (N'tb_app.StageClientInfoRecord',N'P'),
        (N'tb_app.StageClientInfoSecret',N'P'),
        (N'tb_app.ValidateClientInfoImport',N'P'),
        (N'tb_app.CompareClientInfoImportToFireDrill',N'P'),
        (N'tb_security.GetClientInfoImportBatchResult',N'P'),
        (N'tb_app.GetClientInfoImportBatch',N'P'),
        (N'tb_app.ResolveClientInfoImportIssue',N'P'),
        (N'tb_app.AcceptClientInfoImportUnverified',N'P'),
        (N'tb_app.DiscardClientInfoImport',N'P'),
        (N'tb_app.ApproveClientInfoImport',N'P'),
        (N'tb_app.PromoteClientInfoImport',N'P'),
        (N'tb_client.ReparentClientGraph',N'P')
) required([ObjectName],[ObjectType])
WHERE OBJECT_ID(required.[ObjectName],required.[ObjectType]) IS NULL;

IF EXISTS(SELECT 1 FROM @MissingObjects)
BEGIN
    SELECT [ObjectName] FROM @MissingObjects ORDER BY [ObjectName];
    THROW 52502,N'One or more Client Info beta objects are missing.',1;
END;

IF COL_LENGTH(N'tb_client.People', N'AdUsername') IS NULL
   OR COL_LENGTH(N'tb_client.People', N'HasMicrosoft365') IS NULL
   OR COL_LENGTH(N'tb_client.People', N'Microsoft365License') IS NULL
   OR COL_LENGTH(N'tb_client.People', N'PcName') IS NULL
    THROW 52508,N'One or more Client Info user identity columns are missing.',1;

IF COL_LENGTH(N'tb_client.ClientProfiles', N'ClientFolderPath') IS NULL
   OR COL_LENGTH(N'tb_client.ClientProfiles', N'LegacyClientInfoSheetPath') IS NULL
    THROW 52509,N'One or more Client Info server-link columns are missing.',1;

DECLARE @RecordTypeConstraint nvarchar(max)=
    (SELECT [definition]
     FROM sys.check_constraints
     WHERE [parent_object_id]=OBJECT_ID(N'tb_import.ClientInfoRecords')
       AND [name]=N'CK_ClientInfoRecords_Type');
IF @RecordTypeConstraint IS NULL
   OR CHARINDEX(N'ResourceField', @RecordTypeConstraint)=0
    THROW 52510,N'Client Info staging does not allow resource-field records.',1;

DECLARE @ResourceFieldTypeConstraint nvarchar(max)=
    (SELECT [definition]
     FROM sys.check_constraints
     WHERE [parent_object_id]=OBJECT_ID(N'tb_client.ResourceFields')
       AND [name]=N'CK_ClientResourceFields_Type');
DECLARE @FactTypeConstraint nvarchar(max)=
    (SELECT [definition]
     FROM sys.check_constraints
     WHERE [parent_object_id]=OBJECT_ID(N'tb_client.ClientFacts')
       AND [name]=N'CK_ClientFacts_Type');
IF @ResourceFieldTypeConstraint IS NULL
   OR CHARINDEX(N'Phone', @ResourceFieldTypeConstraint)=0
   OR CHARINDEX(N'Email', @ResourceFieldTypeConstraint)=0
   OR @FactTypeConstraint IS NULL
   OR CHARINDEX(N'Phone', @FactTypeConstraint)=0
   OR CHARINDEX(N'Email', @FactTypeConstraint)=0
    THROW 52513,N'Client Info does not support phone and email field types.',1;

IF CERT_ID(N'tb_ClientSecretCertificate') IS NULL
    THROW 52503,N'The canonical client-secret certificate is missing.',1;

IF NOT EXISTS
    (SELECT 1 FROM sys.symmetric_keys WHERE [name]=N'tb_ClientSecretKey')
    THROW 52504,N'The canonical client-secret key is missing.',1;

DECLARE @EncryptClientSecretDefinition nvarchar(max)=
    OBJECT_DEFINITION(OBJECT_ID(N'tb_security.EncryptClientSecretValue'));
DECLARE @SetClientSecretDefinition nvarchar(max)=
    OBJECT_DEFINITION(OBJECT_ID(N'tb_app.SetClientCredentialSecret'));
DECLARE @StageClientSecretDefinition nvarchar(max)=
    OBJECT_DEFINITION(OBJECT_ID(N'tb_app.StageClientInfoSecret'));
IF @EncryptClientSecretDefinition IS NULL
   OR CHARINDEX(N'WITH EXECUTE AS OWNER',@EncryptClientSecretDefinition)=0
   OR CHARINDEX(N'OPEN SYMMETRIC KEY [tb_ClientSecretKey]',@EncryptClientSecretDefinition)=0
   OR CHARINDEX(N'[tb_security].[EncryptClientSecretValue]',@SetClientSecretDefinition)=0
   OR CHARINDEX(N'[tb_security].[EncryptClientSecretValue]',@StageClientSecretDefinition)=0
   OR CHARINDEX(N'WITH EXECUTE AS OWNER',@SetClientSecretDefinition)>0
   OR CHARINDEX(N'WITH EXECUTE AS OWNER',@StageClientSecretDefinition)>0
    THROW 52511,N'Client Info secret writes do not use the protected encryption boundary.',1;

DECLARE @CompareClientInfoDefinition nvarchar(max)=
    OBJECT_DEFINITION(OBJECT_ID(N'tb_app.CompareClientInfoImportToFireDrill'));
DECLARE @GetClientInfoBatchDefinition nvarchar(max)=
    OBJECT_DEFINITION(OBJECT_ID(N'tb_app.GetClientInfoImportBatch'));
IF @CompareClientInfoDefinition IS NULL
   OR CHARINDEX(N'WITH EXECUTE AS OWNER',@CompareClientInfoDefinition)=0
   OR CHARINDEX(N'[tb_security].[GetClientInfoImportBatchResult]',@CompareClientInfoDefinition)=0
   OR CHARINDEX(N'[tb_app].[GetClientInfoImportBatch]',@CompareClientInfoDefinition)>0
   OR CHARINDEX(N'[tb_security].[GetCurrentAccess]',@GetClientInfoBatchDefinition)=0
   OR CHARINDEX(N'[tb_security].[GetClientInfoImportBatchResult]',@GetClientInfoBatchDefinition)=0
    THROW 52512,N'Client Info import results do not preserve the caller security context.',1;

DECLARE @Capabilities nvarchar(max)=
    OBJECT_DEFINITION(OBJECT_ID(N'tb_app.GetRepositoryCapabilities'));
IF CHARINDEX(N'[ClientInfoBetaAvailable]', @Capabilities) = 0
   OR CHARINDEX(N'CONVERT(int, 15) AS [SchemaVersion]', @Capabilities) = 0
    THROW 52505,N'Repository capabilities do not expose the schema-15-compatible Client Info beta.',1;

DECLARE @MergeManual nvarchar(max)=
    OBJECT_DEFINITION(OBJECT_ID(N'tb_app.AdminMergeClients'));
DECLARE @MergeAuto nvarchar(max)=
    OBJECT_DEFINITION(OBJECT_ID(N'tb_service.ApplyAutomaticClientMatch'));
DECLARE @MergeFamily nvarchar(max)=
    OBJECT_DEFINITION(OBJECT_ID(N'tb_service.ApplyAutomaticWhdFamilyMember'));
IF @MergeManual NOT LIKE N'%ReparentClientGraph%'
   OR @MergeAuto NOT LIKE N'%ReparentClientGraph%'
   OR @MergeFamily NOT LIKE N'%ReparentClientGraph%'
    THROW 52506,N'Every client merge path must reparent the canonical Client Info graph.',1;

IF EXISTS
(
    SELECT 1
    FROM sys.database_permissions permission
    WHERE permission.[grantee_principal_id]=DATABASE_PRINCIPAL_ID(N'tb_role_user')
      AND permission.[major_id] IN
        (OBJECT_ID(N'tb_client.CredentialSecrets'),
         OBJECT_ID(N'tb_import.ClientInfoSecrets'))
      AND permission.[state] IN (N'G',N'W')
)
    THROW 52507,N'Ordinary users received direct secret-table permission.',1;

PRINT N'PASS: Client Info beta schema-15 compatibility and security verified.';
GO

-- ============================================================================
-- END 106-V0015-ClientInfoBetaVerify.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 107-V0015-AuthPointMfaVerify.sql
-- ============================================================================

:ON ERROR EXIT

USE [$(DatabaseName)];
GO

SET NOCOUNT ON;
SET XACT_ABORT ON;

IF NOT EXISTS
(
    SELECT 1 FROM [tb_deploy].[SchemaMigrations]
    WHERE [MigrationId]=N'SqlServer2016.AuthPointMfa.0015'
      AND [SchemaVersion]=15
)
    THROW 52490,N'The AuthPoint MFA schema-15 extension is not installed.',1;

IF NOT EXISTS
(
    SELECT 1 FROM [tb_deploy].[SchemaMigrations]
    WHERE [MigrationId]=N'SqlServer2016.AuthPointLoginMfa.0015'
      AND [SchemaVersion]=15
)
    THROW 52490,N'The AuthPoint login MFA schema-15 extension is not installed.',1;

IF OBJECT_ID(N'tb_security.AuthPointUserMappings',N'U') IS NULL
   OR OBJECT_ID(N'tb_security.MfaChallenges',N'U') IS NULL
   OR OBJECT_ID(N'tb_security.MfaLoginSessions',N'U') IS NULL
   OR OBJECT_ID(N'tb_security.MfaBreakGlassGrants',N'U') IS NULL
   OR OBJECT_ID(N'tb_app.GetAuthPointLoginRequirement',N'P') IS NULL
   OR OBJECT_ID(N'tb_app.BeginAuthPointLoginMfaChallenge',N'P') IS NULL
   OR OBJECT_ID(N'tb_app.ActivateAuthPointLoginSession',N'P') IS NULL
   OR OBJECT_ID(N'tb_app.EndAuthPointLoginSession',N'P') IS NULL
   OR OBJECT_ID(N'tb_app.BeginClientSecretMfaChallenge',N'P') IS NULL
   OR OBJECT_ID(N'tb_app.GetClientSecretMfaChallenge',N'P') IS NULL
   OR OBJECT_ID(N'tb_app.CancelClientSecretMfaChallenge',N'P') IS NULL
   OR OBJECT_ID(N'tb_service.GetAuthPointMfaConfiguration',N'P') IS NULL
   OR OBJECT_ID(N'tb_service.ClaimAuthPointMfaChallenge',N'P') IS NULL
   OR OBJECT_ID(N'tb_service.CompleteAuthPointMfaChallenge',N'P') IS NULL
    THROW 52491,N'One or more AuthPoint MFA objects are missing.',1;

IF COL_LENGTH(N'tb_security.MfaChallenges',N'AuthorizationTokenHash') IS NULL
   OR COL_LENGTH(N'tb_security.MfaChallenges',N'AuthorizationTokenEncrypted') IS NULL
   OR COL_LENGTH(N'tb_security.MfaChallenges',N'ChallengeNonceHash') IS NULL
   OR COL_LENGTH(N'tb_security.MfaChallenges',N'ActorWindowsSid') IS NULL
   OR COL_LENGTH(N'tb_security.MfaChallenges',N'ClientInstanceId') IS NULL
   OR COL_LENGTH(N'tb_security.AuthPointUserMappings',N'RequireAtLogin') IS NULL
    THROW 52492,N'The AuthPoint challenge binding columns are incomplete.',1;

IF OBJECT_DEFINITION(OBJECT_ID(N'tb_app.RevealClientCredentialSecret'))
        NOT LIKE N'%AuthorizationToken%'
   OR OBJECT_DEFINITION(OBJECT_ID(N'tb_app.RevealClientCredentialSecret'))
        NOT LIKE N'%ActorWindowsSid%'
   OR OBJECT_DEFINITION(OBJECT_ID(N'tb_app.RevealClientCredentialSecret'))
        NOT LIKE N'%MfaLoginSessions%'
   OR OBJECT_DEFINITION(OBJECT_ID(N'tb_app.RevealClientCredentialSecret'))
        NOT LIKE N'%MfaSessionToken%'
    THROW 52493,N'The canonical secret reveal procedure is not MFA enforcing.',1;

IF OBJECT_DEFINITION(OBJECT_ID(N'tb_app.RevealFireDrillCredential'))
        LIKE N'%AuthPoint%'
   OR OBJECT_DEFINITION(OBJECT_ID(N'tb_app.RevealFireDrillCredential'))
        LIKE N'%MfaChallenge%'
    THROW 52494,N'FireDrill was unexpectedly modified by the AuthPoint extension.',1;

IF EXISTS
(
    SELECT 1 FROM [tb_data].[OrganizationSettings]
    WHERE [SettingKey] IN
        (N'AuthPoint.ApiKey',N'AuthPoint.AccessPassword',N'AuthPoint.BearerToken',
         N'AuthPoint.Secret',N'AuthPoint.SecretKey')
)
    THROW 52495,N'AuthPoint secret material must not be stored in SQL.',1;

IF HAS_PERMS_BY_NAME(N'tb_security.MfaChallenges',N'OBJECT',N'SELECT')=1
   AND IS_ROLEMEMBER(N'tb_role_user')=1
    THROW 52496,N'Desktop users must not directly read MFA challenge storage.',1;

IF HAS_PERMS_BY_NAME(N'tb_security.MfaLoginSessions',N'OBJECT',N'SELECT')=1
   AND IS_ROLEMEMBER(N'tb_role_user')=1
    THROW 52497,N'Desktop users must not directly read MFA login-session storage.',1;

PRINT N'WatchGuard AuthPoint MFA verification passed; schema version remains 15.';
GO

-- ============================================================================
-- END 107-V0015-AuthPointMfaVerify.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 108-V0015-ClientAttachmentsVerify.sql
-- ============================================================================

:ON ERROR EXIT

USE [$(DatabaseName)];
GO

SET NOCOUNT ON;

IF NOT EXISTS
(
    SELECT 1 FROM [tb_deploy].[SchemaMigrations]
    WHERE [MigrationId]=N'SqlServer2016.ClientAttachments.0015'
      AND [SchemaVersion]=15
)
    THROW 52650,N'Client Attachments migration record is missing.',1;

IF NOT EXISTS
(
    SELECT 1 FROM [tb_deploy].[SchemaMigrations]
    WHERE [MigrationId]=N'SqlServer2016.ClientAttachmentEquipmentLinks.0015'
      AND [SchemaVersion]=15
)
    THROW 52656,N'Client Attachment equipment-link migration record is missing.',1;

IF (SELECT MAX([SchemaVersion]) FROM [tb_deploy].[SchemaMigrations])<>15
    THROW 52651,N'Client Attachments must remain compatible with schema version 15.',1;

DECLARE @MissingObjects TABLE([ObjectName] nvarchar(256) NOT NULL);
INSERT INTO @MissingObjects([ObjectName])
SELECT required.[ObjectName]
FROM
(
    VALUES
        (N'tb_client.ClientAttachments',N'U'),
        (N'tb_app.GetClientAttachmentStorageConfiguration',N'P'),
        (N'tb_app.GetClientInfoAttachments',N'P'),
        (N'tb_app.SaveClientInfoAttachment',N'P'),
        (N'tb_app.SetClientInfoAttachmentEquipmentLink',N'P'),
        (N'tb_app.SetClientInfoAttachmentArchived',N'P')
) required([ObjectName],[ObjectType])
WHERE OBJECT_ID(required.[ObjectName],required.[ObjectType]) IS NULL;

IF EXISTS(SELECT 1 FROM @MissingObjects)
BEGIN
    SELECT [ObjectName] FROM @MissingObjects ORDER BY [ObjectName];
    THROW 52652,N'One or more Client Attachments objects are missing.',1;
END;

IF EXISTS
(
    SELECT 1 FROM sys.database_permissions permission
    WHERE permission.[grantee_principal_id]=DATABASE_PRINCIPAL_ID(N'tb_role_user')
      AND permission.[major_id]=OBJECT_ID(N'tb_client.ClientAttachments')
      AND permission.[state] IN (N'G',N'W')
)
    THROW 52653,N'Ordinary users received direct attachment-table permission.',1;

IF NOT EXISTS
(
    SELECT 1 FROM sys.database_permissions permission
    WHERE permission.[grantee_principal_id]=DATABASE_PRINCIPAL_ID(N'tb_role_user')
      AND permission.[major_id]=OBJECT_ID(N'tb_app.GetClientInfoAttachments')
      AND permission.[permission_name]=N'EXECUTE'
      AND permission.[state] IN (N'G',N'W')
)
    THROW 52654,N'Ordinary users cannot list attachment metadata.',1;

DECLARE @SaveDefinition nvarchar(max)=
    OBJECT_DEFINITION(OBJECT_ID(N'tb_app.SaveClientInfoAttachment'));
IF @SaveDefinition NOT LIKE N'%@ContentSha256 binary(32)%'
   OR @SaveDefinition NOT LIKE N'%@ExpectedRowVersion binary(8)%'
   OR @SaveDefinition NOT LIKE N'%WriteAuditEvent%'
    THROW 52655,N'Attachment writes are missing integrity, concurrency, or audit controls.',1;

IF COL_LENGTH(N'tb_client.ClientAttachments',N'EquipmentId') IS NULL
    THROW 52657,N'Client Attachments cannot link to equipment.',1;

DECLARE @LinkDefinition nvarchar(max)=
    OBJECT_DEFINITION(OBJECT_ID(N'tb_app.SetClientInfoAttachmentEquipmentLink'));
IF CHARINDEX(N'[ClientId]=@ClientId',@LinkDefinition)=0
   OR CHARINDEX(N'[IsArchived]=0',@LinkDefinition)=0
   OR @LinkDefinition NOT LIKE N'%@ExpectedRowVersion binary(8)%'
   OR @LinkDefinition NOT LIKE N'%WriteAuditEvent%'
    THROW 52658,N'Attachment equipment links are missing client ownership, concurrency, or audit controls.',1;

PRINT N'PASS: Client Attachments, equipment links, schema-15 compatibility, and security verified.';
GO

-- ============================================================================
-- END 108-V0015-ClientAttachmentsVerify.sql
-- ============================================================================

-- ============================================================================
-- BEGIN 109-V0015-WhdLocalDeleteVerify.sql
-- ============================================================================

:ON ERROR EXIT

USE [$(DatabaseName)];
GO

SET NOCOUNT ON;

DECLARE @Failures int = 0;
DECLARE @DeleteDefinition nvarchar(max) =
    COALESCE(OBJECT_DEFINITION(OBJECT_ID(N'tb_app.DeleteWorkEntry', N'P')), N'');

IF CHARINDEX(N'@ConfirmMissingWhdTechNote bit = 0', @DeleteDefinition) = 0
   OR CHARINDEX(N'IF @SagePosted = 1', @DeleteDefinition) = 0
   OR CHARINDEX(N'IF @WhdPosted = 1', @DeleteDefinition) = 0
   OR CHARINDEX(N'@ConfirmMissingWhdTechNote <> 1', @DeleteDefinition) = 0
BEGIN
    PRINT N'FAIL: DeleteWorkEntry does not require explicit local-delete confirmation while preserving the Sage lock.';
    SET @Failures += 1;
END;

IF CHARINDEX(N'WHD sync pending:%TechNote #%was not found.%', @DeleteDefinition) > 0
   OR CHARINDEX(N'posting_log.[ExternalReference]', @DeleteDefinition) > 0
BEGIN
    PRINT N'FAIL: DeleteWorkEntry still depends on obsolete WHD note synchronization evidence.';
    SET @Failures += 1;
END;

IF CHARINDEX(
       N'FROM [tb_ops].[PostingAttempts] WITH (UPDLOCK, HOLDLOCK)',
       @DeleteDefinition) = 0
   OR CHARINDEX(
       N'FROM [tb_ops].[PostingLeases] WITH (UPDLOCK, HOLDLOCK)',
       @DeleteDefinition) = 0
BEGIN
    PRINT N'FAIL: DeleteWorkEntry no longer protects active external posting operations.';
    SET @Failures += 1;
END;

IF @Failures > 0
    THROW 52226, N'TechBench WHD local-delete verification failed.', 1;

PRINT N'TechBench schema-15-compatible WHD local-delete verification passed.';
GO

-- ============================================================================
-- END 109-V0015-WhdLocalDeleteVerify.sql
-- ============================================================================

PRINT N'TechBench deployment completed successfully on CSRI-SQL.';
GO
